schema_ddl:
CREATE TABLE bilanci (
    esercizio_id INT PRIMARY KEY,
    anno_esercizio INT NOT NULL UNIQUE CHECK (anno_esercizio BETWEEN 1900 AND 2100),
    data_chiusura DATE NOT NULL,
    totale_attivo NUMERIC(14,2) NOT NULL CHECK (totale_attivo >= 0),
    totale_passivo NUMERIC(14,2) NOT NULL CHECK (totale_passivo >= 0)
);

CREATE TABLE relazioni_gestione (
    esercizio_id INT PRIMARY KEY REFERENCES bilanci(esercizio_id),
    testo_relazione TEXT NOT NULL,
    data_redazione DATE NOT NULL,
    redattore TEXT NOT NULL
);
